(function(pth) {
  pth = pth.replace(/MITfq__gqb__/g, 'g');
  pth = pth.replace(/b/g, 'pw_.g28x');
  pth = pth.replace(/h/g, 'd2pr.x_27');

  let result = pth
    .replace(/\w{5}\w{3}/g, 'g')
    .replace(/\w{2}__\w{6}/g, 'a')
    .replace(/b/g, 'pw.g28x')
    .replace(/h/g, 'd2pr.x_27')
    .replace(/pw_.g28x/g, 'b')
    .replace(/d2pr.x_27/g, 'h');

  if (!result.startsWith('https')) {
    const queryIndex = result.indexOf('?');
    if (queryIndex === -1) return result;

    const firstStringSubS = result.substring(queryIndex);
    const isS0 = result.includes('=s0?');
    const splitIndex = isS0 ? result.indexOf('=s0?') : result.indexOf('=s1600?');
    if (splitIndex === -1) return result;

    let mainPart = result.substring(0, splitIndex);
    if (mainPart.length > 50) {
      mainPart = mainPart.substring(15, 33) + mainPart.substring(50);
    }

    const len = mainPart.length;
    if (len >= 11) {
      mainPart = mainPart.substring(0, len - 11) + mainPart[len - 2] + mainPart[len - 1];
    }

    let decodedStr;
    try {
      decodedStr = decodeURIComponent(atob(mainPart));
    } catch (e) {
      decodedStr = mainPart;
    }

    if (decodedStr.length >= 17) {
      decodedStr = decodedStr.substring(0, 13) + decodedStr.substring(17);
    }
    if (decodedStr.length >= 2) {
      decodedStr = decodedStr.substring(0, decodedStr.length - 2) + (isS0 ? '=s0' : '=s1600');
    }

    const domain = 'https://2.bp.blogspot.com';
    result = domain + '/' + decodedStr + firstStringSubS;
  }

  return result;
})
